static int isPalindrome(const char *s, int l, int r) {
  while (l < r) {
    if (s[l] != s[r]) return 0;
    l++;
    r--;
  }
  return 1;
}

static void backtrack(const char *s, int n, int start, char **path, int pathLen,
                      char ****res, int *size, int *cap, int **colSizes) {
  if (start == n) {
    if (*size == *cap) {
      *cap *= 2;
      *res = (char ***)realloc(*res, sizeof(char **) * *cap);
      *colSizes = (int *)realloc(*colSizes, sizeof(int) * *cap);
    }
    char **part = (char **)malloc(sizeof(char *) * (pathLen > 0 ? pathLen : 1));
    for (int i = 0; i < pathLen; i++) {
      int len = (int)strlen(path[i]);
      part[i] = (char *)malloc(len + 1);
      memcpy(part[i], path[i], len + 1);
    }
    (*res)[*size] = part;
    (*colSizes)[*size] = pathLen;
    (*size)++;
    return;
  }

  for (int end = start; end < n; end++) {
    if (!isPalindrome(s, start, end)) continue;
    int len = end - start + 1;
    char *sub = (char *)malloc(len + 1);
    memcpy(sub, s + start, len);
    sub[len] = '\0';
    path[pathLen] = sub;
    backtrack(s, n, end + 1, path, pathLen + 1, res, size, cap, colSizes);
    free(sub);
  }
}

char ***partition(char *s, int *returnSize, int **returnColumnSizes) {
  int n = (int)strlen(s);
  int cap = 16;
  char ***res = (char ***)malloc(sizeof(char **) * cap);
  *returnColumnSizes = (int *)malloc(sizeof(int) * cap);
  *returnSize = 0;
  char **path = (char **)malloc(sizeof(char *) * (n > 0 ? n : 1));
  backtrack(s, n, 0, path, 0, &res, returnSize, &cap, returnColumnSizes);
  free(path);
  return res;
}

class Solution {
  bool isPalindrome(const string &s, int l, int r) {
    while (l < r) {
      if (s[l++] != s[r--]) return false;
    }
    return true;
  }

  void backtrack(const string &s, int start, vector<string> &path, vector<vector<string>> &res) {
    if (start == (int)s.size()) {
      res.push_back(path);
      return;
    }
    for (int end = start; end < (int)s.size(); end++) {
      if (!isPalindrome(s, start, end)) continue;
      path.push_back(s.substr(start, end - start + 1));
      backtrack(s, end + 1, path, res);
      path.pop_back();
    }
  }

public:
  vector<vector<string>> partition(string s) {
    vector<vector<string>> res;
    vector<string> path;
    backtrack(s, 0, path, res);
    return res;
  }
};

func partition(s string) [][]string {
	var res [][]string
	var path []string

	isPalindrome := func(l, r int) bool {
		for l < r {
			if s[l] != s[r] {
				return false
			}
			l++
			r--
		}
		return true
	}

	var backtrack func(start int)
	backtrack = func(start int) {
		if start == len(s) {
			cp := make([]string, len(path))
			copy(cp, path)
			res = append(res, cp)
			return
		}
		for end := start; end < len(s); end++ {
			if !isPalindrome(start, end) {
				continue
			}
			path = append(path, s[start:end+1])
			backtrack(end + 1)
			path = path[:len(path)-1]
		}
	}

	backtrack(0)
	return res
}

class Solution {
  private boolean isPalindrome(String s, int l, int r) {
    while (l < r) {
      if (s.charAt(l++) != s.charAt(r--)) return false;
    }
    return true;
  }

  private void backtrack(String s, int start, List<String> path, List<List<String>> res) {
    if (start == s.length()) {
      res.add(new ArrayList<>(path));
      return;
    }
    for (int end = start; end < s.length(); end++) {
      if (!isPalindrome(s, start, end)) continue;
      path.add(s.substring(start, end + 1));
      backtrack(s, end + 1, path, res);
      path.remove(path.size() - 1);
    }
  }

  public List<List<String>> partition(String s) {
    List<List<String>> res = new ArrayList<>();
    backtrack(s, 0, new ArrayList<>(), res);
    return res;
  }
}

class Solution:
    def partition(self, s: str) -> List[List[str]]:
        res = []
        path = []

        def is_palindrome(l: int, r: int) -> bool:
            while l < r:
                if s[l] != s[r]:
                    return False
                l += 1
                r -= 1
            return True

        def backtrack(start: int) -> None:
            if start == len(s):
                res.append(path[:])
                return
            for end in range(start, len(s)):
                if not is_palindrome(start, end):
                    continue
                path.append(s[start:end + 1])
                backtrack(end + 1)
                path.pop()

        backtrack(0)
        return res

impl Solution {
  pub fn partition(s: String) -> Vec<Vec<String>> {
    fn is_palindrome(bytes: &[u8], mut l: usize, mut r: usize) -> bool {
      while l < r {
        if bytes[l] != bytes[r] {
          return false;
        }
        l += 1;
        r -= 1;
      }
      true
    }

    fn backtrack(bytes: &[u8], start: usize, path: &mut Vec<String>, res: &mut Vec<Vec<String>>) {
      if start == bytes.len() {
        res.push(path.clone());
        return;
      }
      for end in start..bytes.len() {
        if is_palindrome(bytes, start, end) {
          path.push(String::from_utf8(bytes[start..=end].to_vec()).unwrap());
          backtrack(bytes, end + 1, path, res);
          path.pop();
        }
      }
    }

    let bytes = s.into_bytes();
    let mut res = vec![];
    let mut path = vec![];
    backtrack(&bytes, 0, &mut path, &mut res);
    res
  }
}

const partition = (s: string): string[][] => {
  const res: string[][] = [];
  const path: string[] = [];

  const isPalindrome = (l: number, r: number): boolean => {
    while (l < r) {
      if (s[l++] !== s[r--]) return false;
    }
    return true;
  };

  const backtrack = (start: number): void => {
    if (start === s.length) {
      res.push([...path]);
      return;
    }
    for (let end = start; end < s.length; end++) {
      if (!isPalindrome(start, end)) continue;
      path.push(s.slice(start, end + 1));
      backtrack(end + 1);
      path.pop();
    }
  };

  backtrack(0);
  return res;
};
